import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import '../today/today_screen.dart';
class PlanScreen extends ConsumerWidget{const PlanScreen({super.key});@override Widget build(BuildContext c,WidgetRef r)=>Scaffold(appBar:AppBar(title:const Text('План')),body:r.watch(planProvider).when(data:(p)=>ListView(padding:const EdgeInsets.all(24),children:[Text('Этап: ${p.state}',style:Theme.of(c).textTheme.headlineMedium),Text(p.action.title),Text('Свободный поток: ${money(p.snapshot.monthlyFreeCashFlow,p.currency)}'),...p.forecasts.values.map((f)=>ListTile(title:Text(f.strategy),subtitle:Text(f.debtFreeDate==null?'Горизонт более 30 лет':'Без долгов: ${f.debtFreeDate?.toIso8601String().substring(0,10) ?? ''}'),trailing:Text(money(f.totalPaid,p.currency))))]),loading:()=>const Center(child:CircularProgressIndicator()),error:(e,_)=>Center(child:Text('$e'))));}
